#include <WiFi.h>
#include <WebServer.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;
WebServer server(80);

// ===== Список сетей: имя и пароль идут парами =====
const char* WIFI_SSIDS[] = {"KIBERone5", "KIBERone"};
const char* WIFI_PASSS[] = {"KIBERone", "KIBERone"};
const int   WIFI_COUNT   = sizeof(WIFI_SSIDS) / sizeof(WIFI_SSIDS[0]);

// Если нужно поднять свою точку доступа — раскомментируй:
// #define AP_MODE

const int TRIGGER_PIN = 0;    // кнопка BOOT — запуск печати
const int CHAR_DELAY  = 60;   // пауза между символами, мс
const int TYPE_DELAY  = 1500; // пауза перед началом набора, мс

volatile bool pending = false;
String payloadText = "";

// ===== Подключение: перебираем сети, берём первую найденную =====
void connectWiFi() {
  Serial.println("Сканирую сети...");

  int n = WiFi.scanNetworks();
  if (n <= 0) {
    Serial.println("Сети не найдены!");
    return;
  }

  // Идём по найденным сетям и ищем совпадение с нашим списком
  for (int i = 0; i < n; i++) {
    String found = WiFi.SSID(i);
    for (int j = 0; j < WIFI_COUNT; j++) {
      if (found == WIFI_SSIDS[j]) {
        Serial.printf("Найдена \"%s\", подключаюсь...\n", WIFI_SSIDS[j]);
        WiFi.begin(WIFI_SSIDS[j], WIFI_PASSS[j]);

        // Ждём подключения до 15 секунд
        unsigned long start = millis();
        while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) {
          delay(500);
          Serial.print(".");
        }
        Serial.println();
        if (WiFi.status() == WL_CONNECTED) {
          Serial.print("Подключено к ");
          Serial.print(WIFI_SSIDS[j]);
          Serial.print(", IP: ");
          Serial.println(WiFi.localIP());
          return;
        }
        Serial.println("Не подключилось, пробую следующую сеть.");
      }
    }
  }
  Serial.println("Ни одна сеть не подключилась.");
}

const char* PAGE_HTML = R"rawliteral(
<!DOCTYPE html><html><head>
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ESP32 HID</title>
<style>
  body{font-family:sans-serif;max-width:600px;margin:30px auto;padding:0 15px}
  textarea{width:100%;height:120px;font-size:16px;box-sizing:border-box}
  button{padding:10px 24px;font-size:16px;margin-top:8px}
  #log{margin-top:15px;color:#555}
</style></head><body>
<h2>ESP32 WiFi Keyboard</h2>
<textarea id="txt" placeholder="Текст для набора (Enter = нажатие Enter)"></textarea><br>
<button onclick="send()">Напечатать</button>
<button onclick="sendCmd('color 2\ndir /s')">Пример: cmd</button>
<div id="log"></div>
<script>
function send(){
  fetch('/type?text=' + encodeURIComponent(document.getElementById('txt').value))
    .then(r=>r.text()).then(t=>log(t));
}
function sendCmd(t){
  document.getElementById('txt').value = t; send();
}
function log(m){document.getElementById('log').textContent = m;}
</script></body></html>
)rawliteral";

void typeText(String text) {
  for (unsigned int i = 0; i < text.length(); i++) {
    char c = text[i];
    if (c == '\n') {
      Keyboard.press(KEY_RETURN);
      Keyboard.releaseAll();
    } else {
      Keyboard.write(c);
    }
    delay(CHAR_DELAY);
  }
}

void handleRoot() { server.send(200, "text/html", PAGE_HTML); }

void handleType() {
  if (server.hasArg("text")) {
    payloadText = server.arg("text");
    pending = true;
    server.send(200, "text/plain", "OK: печать запущена");
  } else {
    server.send(400, "text/plain", "нет параметра text");
  }
}

void setup() {
  pinMode(TRIGGER_PIN, INPUT_PULLUP);
  Serial.begin(115200);

  Keyboard.begin();
  USB.begin();
  delay(2000);   // время системе распознать клавиатуру

#ifdef AP_MODE
  WiFi.softAP("ESP32-HID", "");
  Serial.print("AP запущен. Открой http://");
  Serial.println(WiFi.softAPIP());   // обычно 192.168.4.1
#else
  WiFi.mode(WIFI_STA);
  connectWiFi();
#endif

  server.on("/", handleRoot);
  server.on("/type", handleType);
  server.begin();
  Serial.println("Веб-сервер запущен.");
}

void loop() {
  server.handleClient();

  // Переподключаемся, если связь отвалилась
  if (WiFi.status() != WL_CONNECTED) {
    static unsigned long lastTry = 0;
    if (millis() - lastTry > 30000) {   // раз в 30 секунд
      lastTry = millis();
      connectWiFi();
    }
  }

  // Печать запускается кнопкой BOOT
  if (pending && digitalRead(TRIGGER_PIN) == LOW) {
    delay(80);
    pending = false;
    Serial.println("Печатаю...");
    delay(TYPE_DELAY);
    typeText(payloadText);
    Serial.println("Готово");
  }
  delay(10);
}
